def call_limit(count):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kw):
            if wrapper.calls >= count:
                raise CallLimitExceededError(f"Function '{func.__name__}' has exceeded the call limit of {count}")
            wrapper.calls += 1
            return func(*args, **kw)
        wrapper.calls = 0
        return wrapper
    return decorator

