class CadenceDictionary:
    def __init__(self):
        self._data = {}
        self._order = []

    def add(self, key, value):
        if key in self._data:
            self._data[key] = value
        else:
            self._data[key] = value
            self._order.append(key)

    def get(self, key):
        return self._data.get(key, None)

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            self._order.remove(key)

