    def get_order_by_clause(self) -> str:
        if self.order_by:
            return f"ORDER BY {self.order_by} {self.order_by_direction}"
        return ""

    def get_limit_offset_clause(self) -> str:
        if self.page_size and self.page_number:
            offset = (self.page_number - 1) * self.page_size
            return f"LIMIT {self.page_size} OFFSET {offset}"
        return ""

