function loadAndUseModule(directoryPath) {
  return new Promise((resolve, reject) => {
    const modulePath = path.join(directoryPath, 'dist', 'interpret.js');
    fs.access(modulePath, fs.constants.R_OK, (err) => {
      if (err) {
        reject(`Error accessing module at ${modulePath}`);
      } else {
        try {
          const module = require(modulePath);
          if (typeof module.create === 'function') {
            const result = module.create();
            resolve(result);
          } else {
            reject('Module does not export a create function');
          }
        } catch (error) {
          reject(`Error loading module: ${error.message}`);
        }
      }
    });
  });
}

