def process_log_file(log_file_path):
    log_data = []
    lines_error = []

    with open(log_file_path, 'r') as file:
        num_errors = 0
        for line_index, line in enumerate(file):
            line = line.strip()
            parts = line.split(',')
            data = {}
            for part in parts:
                key, value = part.split(':')
                data[key.strip()] = value.strip()
            if all(key in data for key in ['timestamp', 'level', 'message']):
                log_data.append(data)
            else:
                lines_error.append((line_index, line))
                num_errors += 1

    return log_data, lines_error

