from datetime import timedelta

def _parse_offset(raw_offset):
    """Parse the offset."""
    if raw_offset is None:
        return timedelta(0)

    negative_offset = False
    if raw_offset.startswith('-'):
        negative_offset = True
        raw_offset = raw_offset[1:]  # Remove the negative sign

    hours, minutes, seconds = map(int, raw_offset.split(':'))

    if negative_offset:
        offset_timedelta = timedelta(hours=hours, minutes=minutes, seconds=seconds)
        return -offset_timedelta
    else:
        return timedelta(hours=hours, minutes=minutes, seconds=seconds)

