def analyze_resource_usage(pages, quota_data, value, threshold_requested):
    overused_resources = []
    usage = 0

    for page in pages:
        usage += len(page[quota_data["key"]])

    try:
        percent = round((usage / value) * 100, 2)
    except ZeroDivisionError:
        percent = 0

    if percent >= threshold_requested:
        resource_found = Resource(
            digest=ResourceDigest(
                id=quota_data["quota_code"], type="aws_limit"
            )
        )
        overused_resources.append(resource_found)

    return overused_resources

