class VotingRecordProcessor:
    def __init__(self):
        self.dvr = {}

    def parse_row(self, row: List[str]) -> DistrictVotingRecord:
        district = row[0]
        if row[1] == 'EVEN':
            political_leaning = 0
        elif row[1][0] == 'R':
            political_leaning = float(row[1][2:])
        else:
            political_leaning = -float(row[1][2:])
        voter_turnout = float(row[2])
        return DistrictVotingRecord(district, political_leaning, voter_turnout)

    def process_records(self, data: List[List[str]]) -> None:
        for row in data:
            dvr = self.parse_row(row)
            self.dvr[dvr.district] = dvr

