def download_file(url: str, destination: str) -> bool:
    try:
        response = requests.get(url, stream=True)
        if response.status_code == 200:
            with open(destination, 'wb') as file:
                for chunk in response.iter_content(chunk_size=1024):
                    if chunk:
                        file.write(chunk)
            return True
        else:
            return False
    except requests.exceptions.RequestException:
        return False

def lookup(queues, filter_by=None):
    if filter_by is None:
        return queues  # Return all queues if no filter criteria is specified

    filtered_queues = []
    for queue in queues:
        if all(getattr(queue, attr, None) == value for attr, value in filter_by.items()):
            filtered_queues.append(queue)

    return filtered_queues

