class Calculator:
    def __init__(self):
        self.display = "0"
        self.current_operator = None
        self.previous_value = 0

    def verifyInput(self, key):
        if key.isdigit():
            if self.display == "0":
                self.display = key
            else:
                self.display += key
        elif key in ['+', '-', '*', '/']:
            if self.current_operator is not None:
                self.calculate()
            self.current_operator = key
            self.previous_value = int(self.display)
            self.display = "0"
        elif key == '\r':
            self.calculate()
        else:
            print("Invalid input")

    def calculate(self):
        if self.current_operator is not None:
            if self.current_operator == '+':
                self.display = str(self.previous_value + int(self.display))
            elif self.current_operator == '-':
                self.display = str(self.previous_value - int(self.display))
            elif self.current_operator == '*':
                self.display = str(self.previous_value * int(self.display))
            elif self.current_operator == '/':
                if int(self.display) != 0:
                    self.display = str(self.previous_value / int(self.display))
                else:
                    print("Error: Division by zero")
            self.current_operator = None
            self.previous_value = 0

