def pathSum(root, targetSum):
    def dfs(node, targetSum, prefixSum, prefixSumCount):
        if not node:
            return 0
        prefixSum += node.val
        count = prefixSumCount.get(prefixSum - targetSum, 0)
        prefixSumCount[prefixSum] = prefixSumCount.get(prefixSum, 0) + 1
        count += dfs(node.left, targetSum, prefixSum, prefixSumCount) + dfs(node.right, targetSum, prefixSum, prefixSumCount)
        prefixSumCount[prefixSum] -= 1
        return count

    prefixSumCount = {0: 1}
    return dfs(root, targetSum, 0, prefixSumCount)

