def calculate_learning_rate(iteration):
    LR = 1e-3
    DECAY_STEP = [12000, 16000, 20000]
    for step in DECAY_STEP:
        if iteration <= step:
            return LR * (0.5 ** (iteration / step))
    return LR * (0.5 ** (iteration / DECAY_STEP[-1]))

