def apply_dropout(input_data, dropout_ratio, training_mode):
    if training_mode:
        dropout_mask = tf.random.uniform(tf.shape(input_data)) > dropout_ratio
        dropped_out_data = tf.where(dropout_mask, input_data, tf.zeros_like(input_data))
        scaled_data = dropped_out_data / (1 - dropout_ratio)  # Scale the remaining units during training
        return scaled_data
    else:
        return input_data  # Return input data unchanged during inference

