def setup_decimal_context(context):
    context.prec = 7

def calculate_pi():
    getcontext().prec = 50  # Set precision to a higher value for accurate calculation
    one = Decimal(1)
    pi = Decimal(0)
    k = 0
    while True:
        term = (one / 16 ** k) * (
            (four(1, k) - two(4, k) - one(5, k) - one(6, k))
        )
        if term == 0:
            break
        pi += term
        k += 1
    return +pi

