def configure_network(commands: List[str]) -> Dict[str, Dict[str, Union[str, bool]]]:
    network_state = {}

    for command in commands:
        tokens = command.split()
        if tokens[2] == "set":
            interface = tokens[4]
            state = tokens[6]
            network_state[interface] = {"state": state}
        elif tokens[2] == "add":
            name = tokens[3]
            if tokens[5] == "type" and tokens[6] == "bridge":
                bridge_props = {"state": "down", "vlan_filtering": False}
                if "vlan_filtering" in tokens:
                    bridge_props["state"] = "up"
                    bridge_props["vlan_filtering"] = True
                network_state[name] = bridge_props

    return network_state

