class ParkingLot:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.occupied_spaces = set()

    def park(self, vehicle_id: int) -> None:
        if len(self.occupied_spaces) < self.capacity:
            self.occupied_spaces.add(vehicle_id)
            print(f"Vehicle {vehicle_id} parked successfully")
            self.log_event(ParkingLotEvent.PARK, vehicle_id)
        else:
            print("Parking lot is full")

    def retrieve(self, vehicle_id: int) -> None:
        if vehicle_id in self.occupied_spaces:
            self.occupied_spaces.remove(vehicle_id)
            print(f"Vehicle {vehicle_id} retrieved successfully")
        else:
            print("Vehicle not found")

    def log_event(self, event: ParkingLotEvent, vehicle_id: int) -> None:
        # Log the parking lot event
        print(f"Event logged: {event.name} - Vehicle {vehicle_id}")

