import asyncio
from typing import List, Coroutine

async def run_event_loop(tasks: List[Coroutine]):
    while tasks:
        for task in tasks[:]:
            try:
                await task
            except asyncio.CancelledError:
                tasks.remove(task)
            except StopIteration:
                tasks.remove(task)
        await asyncio.sleep(0)  # Allow other tasks to run

def calculate_shipping_cost(packages, destinations, rates):
    total_cost = 0
    for i in range(len(packages)):
        weight = packages[i]
        destination = destinations[i]
        if weight <= rates[destination]['max']:
            for weight_range, cost in sorted(rates[destination].items()):
                if weight <= weight_range:
                    total_cost += cost
                    break
        else:
            total_cost += rates[destination]['additional_fee']
    return total_cost

