        print(f"File '{file}' not found.")
        sys.exit(1)

    if count.startswith('+'):
        count = int(count[1:])
        lines = lines[:-count]
    elif count.startswith('-'):
        count = int(count[1:])
        lines = lines[count:]
    else:
        count = int(count)
        lines = lines[:count]

    for line in lines:
        print(line, end='')

