    v1 = list(map(int, version1.split('.')))
    v2 = list(map(int, version2.split('.'))

    # Make the version lists equal in length by appending zeros
    while len(v1) < len(v2):
        v1.append(0)
    while len(v2) < len(v1):
        v2.append(0)

    # Compare each segment of the version numbers
    for i in range(len(v1)):
        if v1[i] > v2[i]:
