use std::fmt::Display;

struct FormatTreeNode<T>
where
    T: Display,
{
    payload: T,
    children: Vec<FormatTreeNode<T>>,
}

impl<T> FormatTreeNode<T>
where
    T: Display,
{
    pub fn new(payload: T) -> Self {
        Self {
            payload,
            children: Vec::new(),
        }
    }

    pub fn add_child(&mut self, child: FormatTreeNode<T>) {
        self.children.push(child);
    }

    pub fn display(&self, level: usize) {
        println!("{}{}", "  ".repeat(level), self.payload);
        for child in &self.children {
            child.display(level + 1);
        }
    }
}

