import numpy as np

class WeightedBinaryCrossEntropy(LossFunction):
    """Loss function which is used for binary-class classification with weighted samples."""
    def get_type(self):
        return 'weighted binary cross entropy'

    def get(self, y, t, w):
        error = -w * (t * np.log(y + self.ep) + (1 - t) * np.log(1 - y + self.ep))
        return error.sum() / y.shape[0]

