from typing import Tuple

class Term:
    def __init__(self, symbol, subterms):
        self.symbol = symbol
        self.subterms = subterms

def process_expression(term: Term) -> Tuple[str, str, Tuple[int]]:
    def find_outermost_symbol(term):
        if not term.subterms:
            return term.symbol
        return find_outermost_symbol(term.subterms[0])

    def find_subterm_indices(term, symbol, indices=[]):
        if term.symbol == symbol:
            return indices
        for i, subterm in enumerate(term.subterms):
            indices.append(i)
            result = find_subterm_indices(subterm, symbol, indices)
            if result is not None:
                return result
            indices.pop()
        return None

    outermost_symbol = find_outermost_symbol(term)
    sign = '+' if outermost_symbol in ['+', '*'] else '-'
    indices = find_subterm_indices(term, outermost_symbol)
    return sign, outermost_symbol, tuple(indices)

