def process_image(im, orientation):
    im = [[255 - pixel for pixel in row] for row in im]  # Invert pixel values
    if orientation == 1:
        x = [sum(column) for column in zip(*im)]  # Sum along columns
    else:
        x = [sum(row) for row in im]  # Sum along lines
    return x

