from collections import defaultdict

class Event:
    def __init__(self):
        self.handlers = defaultdict(list)

    def send(self, event, **kwargs):
        for handler in self.handlers[event]:
            handler(**kwargs)

    def receiver(self, event):
        def decorator(func):
            self.handlers[event].append(func)
            return func
        return decorator

install_options = Event()

@install_options.receiver('install')
def _install_app_options(app, options):
    print(f"Received installation options for {app}: {options}")

# Example usage
